import test from "node:test";
import assert from "node:assert/strict";
import {createJobBundle,validateJobBundle,validateImageFile,verifyImportedResult,sha256Hex,MAX_RESULT_BYTES,transitionBundleState} from "../src/bundles.js";
const png=new Uint8Array([137,80,78,71,13,10,26,10,0,0,0,0]);
const mp4Bytes=new Uint8Array([0,0,0,24,102,116,121,112,105,115,111,109,0,0,2,0,0,0,0,8]);
async function setup(){const job=await createJobBundle({prompt:"A quiet forest",totalSeconds:5,seed:17});const video=new Blob([mp4Bytes],{type:"video/mp4"});const manifest={schemaVersion:1,status:"completed",jobId:job.jobId,kind:"ai_generated",engine:{id:"ltx-video",model:"Lightricks/LTX-Video",revision:null,license:"see docs"},hardware:{gpu:"self-reported GPU"},scenes:[{index:1,status:"completed",frames:121,file:"scenes/scene-001.mp4",sha256:"1".repeat(64)}],final:{file:"result.mp4",sha256:await sha256Hex(video),duration:5,width:512,height:288,fps:"24/1",codec:"h264"}};return{job,video,manifest}}
test("bundle creation follows schema v1 and plans six scenes for 30 seconds",async()=>{const b=await createJobBundle({prompt:"A red kite",totalSeconds:30,seed:42});assert.equal(b.schemaVersion,1);assert.match(b.jobId,/^[0-9a-f]{32}$/);assert.equal(b.scenes.length,6);assert.equal(b.scenes[0].prompt,"A red kite — continues the same scene with consistent subject, setting, lighting, and camera motion.");assert.equal(await validateJobBundle(b),true)});
test("Long preset is 30 seconds and bundle has random 128-bit id",async()=>{const a=await createJobBundle({prompt:"x",totalSeconds:30,seed:1}),b=await createJobBundle({prompt:"x",totalSeconds:30,seed:1});assert.equal(a.preset,"Long");assert.notEqual(a.jobId,b.jobId)});
test("image validation checks MIME, size and magic bytes",async()=>{const good=new Blob([png],{type:"image/png"});assert.equal((await validateImageFile(good)).ok,true);const bad=new Blob([new Uint8Array([1,2,3,4,5,6,7,8])],{type:"image/png"});assert.equal((await validateImageFile(bad)).ok,false);const wrongType=new Blob([png],{type:"image/gif"});assert.equal((await validateImageFile(wrongType)).ok,false)});
test("oversized starting image is rejected",async()=>{const huge={type:"image/png",size:10*1024*1024+1};assert.equal((await validateImageFile(huge)).ok,false)});
test("bundle validator rejects a wrong schema version",async()=>{const b=await createJobBundle({prompt:"x",totalSeconds:5,seed:1});b.schemaVersion=99;await assert.rejects(validateJobBundle(b),/schema/)});
test("image bundle records matching SHA-256 and base64",async()=>{const b=await createJobBundle({prompt:"image",totalSeconds:5,seed:1,image:new Blob([png],{type:"image/png"})});assert.equal(b.mode,"image");assert.equal(b.image.sha256,await sha256Hex(png.buffer.slice(png.byteOffset,png.byteOffset+png.byteLength)));assert.ok(b.image.base64.length>0)});
test("manifest import succeeds only when bundle id, schema, signature and SHA match",async()=>{const {job,video,manifest}=await setup();const v=await verifyImportedResult(video,manifest,job);assert.equal(v.kind,"ai_generated");assert.equal(v.model,"Lightricks/LTX-Video")});
test("manifest import rejects wrong SHA-256",async()=>{const x=await setup();x.manifest.final.sha256="0".repeat(64);await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/SHA-256 mismatch/)});
test("manifest import rejects wrong jobId",async()=>{const x=await setup();x.manifest.jobId="f".repeat(32);await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/jobId/)});
test("manifest import rejects wrong schema",async()=>{const x=await setup();x.manifest.schemaVersion=9;await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/schemaVersion/)});
test("manifest import rejects oversized video before reading it",async()=>{const x=await setup();const oversized={size:MAX_RESULT_BYTES+1,slice:()=>x.video.slice(0,16)};await assert.rejects(verifyImportedResult(oversized,x.manifest,x.job),/512 MiB/)});
test("failed/incomplete manifest is never importable",async()=>{const x=await setup();x.manifest.status="failed";await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/not marked completed/)});
test("manifest kind spoof attempt with unknown kind is rejected",async()=>{const x=await setup();x.manifest.kind="verified_ai";await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/Invalid manifest kind/)});
test("test-pattern manifest is accepted only as a test-pattern label",async()=>{const x=await setup();x.manifest.kind="test_pattern";x.manifest.engine={id:"fake-test-pattern",model:"ffmpeg:testsrc",revision:null,license:"test only"};const v=await verifyImportedResult(x.video,x.manifest,x.job);assert.equal(v.kind,"test_pattern")});
test("AI kind cannot be spoofed with the test-only engine identity",async()=>{const x=await setup();x.manifest.engine={id:"fake-test-pattern",model:"ffmpeg:testsrc",revision:null,license:"test only"};await assert.rejects(verifyImportedResult(x.video,x.manifest,x.job),/AI kind is not valid/)});
test("bundle state machine includes awaiting_worker, importing, completed, failed and cancelled",()=>{for(const s of ["awaiting_worker","importing","completed","failed","cancelled"])assert.ok(s);assert.equal(transitionBundleState("awaiting_worker","importing"),true);assert.equal(transitionBundleState("importing","completed"),true);assert.equal(transitionBundleState("completed","failed"),false);assert.equal(transitionBundleState("awaiting_worker","cancelled"),true);assert.equal(transitionBundleState("failed","importing"),true);assert.equal(transitionBundleState("completed","importing"),true)});
